const b = $json.body || {};
const item = {
  event_id: b.event_id,
  event_type: b.event_type,
  source: b.source,
  severity: b.severity || 'unknown',
  service: b.service || 'unknown',
  payload: b.payload || {},
  started_at: new Date().toISOString(),
};
item.response = { accepted: true, event_id: item.event_id, execution_id: $execution.id, workflow: 'incident-ticket' };
return [{ json: item }];

const i = $('Init & Start Timer').item.json;
return [{ json: { publish: {
  event_id: 'evt_' + $execution.id + '-result',
  event_type: 'incident.ticket_created',
  source: 'n8n.incident-ticket',
  timestamp: new Date().toISOString(),
  correlation_id: i.event_id,
  correlation_workflow: 'incident-ticket',
  severity: i.severity,
  service: i.service,
  payload: { ticket_id: $json.ticket_id, key: $json.key, backend: $json.backend, started_at: i.started_at }
} } }];

const i = $('Init & Start Timer').item.json;
const err = $json && $json.error ? ($json.error.message || JSON.stringify($json.error)) : 'ticket creation failed';
return [{ json: { publish: {
  event_id: 'evt_' + $execution.id + '-result',
  event_type: 'system.workflow_failed',
  source: 'n8n.incident-ticket',
  timestamp: new Date().toISOString(),
  correlation_id: i.event_id,
  correlation_workflow: 'incident-ticket',
  severity: 'critical',
  service: i.service,
  payload: { failed_workflow: 'incident-ticket', error: String(err) }
} } }];

const i = $('Init & Start Timer').item.json;
return [{ json: { publish: {
  event_id: 'evt_' + $execution.id + '-result',
  event_type: 'incident.ticket_skipped',
  source: 'n8n.incident-ticket',
  timestamp: new Date().toISOString(),
  correlation_id: i.event_id,
  correlation_workflow: 'incident-ticket',
  severity: i.severity,
  service: i.service,
  payload: { reason: 'severity below high' }
} } }];
